<template>
  <div :id="'PieCharts' + id" :style="{ width: '100%', height: '100%' }"></div>
</template>

<script>
import echarts from '@/views/bigScreen/com/echarts'; 
import { echartsMixin } from '../../com/echartsMixin';

export default {
  name: 'PieCharts',
  mixins: [echartsMixin],
  props: {
    echartsData: {
      type: Object,
      default: () => {},
    },

    id: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      myEchart: null,
    };
  },
  methods: {
    initChart() {
      const chartDom = document.getElementById('PieCharts' + this.id);
      if (!chartDom) return;

      this.myEchart = echarts.init(chartDom);

      const option = {
        title: {
          text: 'XX',
          left: 'center',
          top: 'center',
          textStyle: {
            fontSize: 30,
            fontFamily: 'Alimama ShuHeiTi',
            fontWeight: '700',
            color: '#fff',
          },
        },
        graphic: [
          {
            type: 'text',
            left: 'center',
            bottom: '20%',
            style: {
              text: '分类统计',
              fill: '#fff',
              textAlign: 'center',
              fontSize: 16,
              fontFamily: 'PingFang SC',
              fontWeight: '500',
            },
          },
          {
            type: 'image',
            left: 'center',
            bottom: '8%',
            z: -10,
            bounding: 'all',
            rotation: 0, //旋转
            scale: [1.0, 1.0], //缩放
            style: {
              opacity: 1,
              width: 164,
              height: 40,
              image:
                'data:image/png;base64,',
            },
          },
        ],
        series: [
          {
            type: 'gauge',
            radius: '90',
            center: ['50%', '50%'],
            min: 0,
            max: 100,
            startAngle: 225,
            endAngle: -45,
            axisLine: {
              show: true,
              lineStyle: {
                // 轴线样式
                width: 30, // 宽度
                color: [
                  [1, 'rgba(255, 255, 255, 0.1)'],
                ],
              },
            },
            axisTick: {
              // 刻度
              show: false,
            },
            splitLine: {
              // 分割线
              show: false,
            },
            axisLabel: {
              // 刻度标签
              show: false,
            },
            detail: {
              // 仪表盘详情
              show: false,
            },
          },
          {
            // 进度条圆环带底
            type: 'gauge',
            radius: '90',
            center: ['50%', '50%'],
            startAngle: 225,
            endAngle: -45,
            // 底部
            axisLine: {
              lineStyle: {
                color: [[1, 'rgba(255, 255, 255, 0.2)']],
                width: 15,
              },
            },
            axisTick: {
              show: false,
            },
            splitLine: {
              show: false,
            },
            axisLabel: {
              show: false,
            },
            detail: {
              show: false,
            },
            progress: {
              show: true,
              width: 15,
              // 进度条圆环
              itemStyle: {
                color: {
                  type: 'linear',
                  x: 0,
                  y: 1,
                  x2: 0,
                  y2: 0,
                  colorStops: [
                    {
                      offset: 0,
                      color: '#00A3FF',
                    },
                    {
                      offset: 0.8,
                      color: '#BDFF00',
                    },
                  ],
                },
              },
            },
            pointer: {
              show: false,
            },
            data: [
              {
                value: this.echartsData.percent,
              },
            ],
          },
        ],
      };

      this.myEchart.setOption(option);
    },
  },
};
</script>